package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type DiscRec struct {
	DrItem  string
	DrPrice decimal.Decimal
	DrPct   int64
}

var WsEofFlag string = "N"
var WsDiscount decimal.Decimal = decimal.NewFromInt(0)
var WsNet decimal.Decimal = decimal.NewFromInt(0)
var WsTotalNet decimal.Decimal = decimal.NewFromInt(0)
var WsCount int64 = 0
var WsPriceEd string
var WsDiscEd string
var WsNetEd string
var WsTotalEd string

var discFile *os.File
var discReader *bufio.Reader
var discRec DiscRec
var atEnd bool

func truncateToScale(d decimal.Decimal, scale int32) decimal.Decimal {
	return d.Truncate(scale)
}
func roundToScale(d decimal.Decimal, scale int32) decimal.Decimal {
	return d.Round(scale)
}

func fitToPic9V99(d decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	// truncate/round already done before calling; now enforce overflow truncation
	// keep low-order digits: modulo 10^(intDigits+scale) then adjust scale
	// Represent d as integer of scale: d * 10^scale
	// But simpler: using decimal's Coefficient
	// We can compute modulo by using integer arithmetic on the unscaled value.
	// Use truncation to scale first
	d = d.Truncate(scale)
	// Get unscaled integer
	// d = coeff * 10^exp ; we want integer = d * 10^scale
	shifted := d.Shift(scale) // d * 10^scale
	// shifted should be integer
	modPow := decimal.NewFromInt(1).Shift(int32(intDigits + int(scale))) // 10^(intDigits+scale)
	// modulo keeping sign positive? COBOL fields unsigned here, values positive.
	// For positive, remainder is shifted % modPow
	// For negative, COBOL truncation keeps sign but low digits? Not needed here.
	if shifted.IsNegative() {
		// keep sign, modulo on abs
		abs := shifted.Abs()
		rem := abs.Mod(*modPow)
		shifted = rem.Neg()
	} else {
		rem := shifted.Mod(*modPow)
		shifted = rem
	}
	return shifted.Shift(-scale)
}

func storeDiscount(d decimal.Decimal) {
	WsDiscount = fitToPic9V99(d, 5, 2)
}
func storeNet(d decimal.Decimal) {
	WsNet = fitToPic9V99(d, 5, 2)
}
func storeTotalNet(d decimal.Decimal) {
	WsTotalNet = fitToPic9V99(d, 8, 2)
}

func formatEdited(d decimal.Decimal, picture string) string {
	width := len(picture)
	// split picture at '.'
	dotIdx := strings.Index(picture, ".")
	var intPic, fracPic string
	var fracLen int
	if dotIdx >= 0 {
		intPic = picture[:dotIdx]
		fracPic = picture[dotIdx+1:]
		fracLen = len(fracPic)
	} else {
		intPic = picture
		fracPic = ""
		fracLen = 0
	}
	// count digit slots in intPic
	intSlots := 0
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			intSlots++
		}
	}
	// absolute value for display; assume positive
	abs := d.Abs()
	// truncate toward zero to scale fracLen (COBOL MOVE truncates? but display of edited field)
	// For these moves, value already has correct scale; just format.
	// Ensure we have integer and fractional parts
	// Get integer part
	intPart := abs.Truncate(0)
	// fractional part: abs - intPart, scaled
	// Format fractional digits
	fracStr := ""
	if fracLen > 0 {
		// get abs with fracLen digits
		shifted := abs.Shift(int32(fracLen)).Truncate(0)
		// fractional = shifted % 10^fracLen
		mod := decimal.NewFromInt(1).Shift(int32(fracLen))
		fracVal := shifted.Mod(*mod)
		// need absolute mod
		if fracVal.IsNegative() {
			fracVal = fracVal.Neg()
		}
		fracInt64 := fracVal.IntPart()
		fracStr = fmt.Sprintf("%0*d", fracLen, fracInt64)
		// Integer part for display uses intPart's low-order digits already handled by fit
		// But if integer part has more digits than slots, high-order dropped for display
		// That dropping already done via fit? For edited fields, same rule: drop high-order
		// We'll handle below
		_ = intPart
	}

	// Prepare integer digits string with leading zeros to intSlots
	// Get integer part absolute value as decimal integer
	intAbsStr := intPart.Abs().StringFixed(0) // no decimal
	if intAbsStr == "" {
		intAbsStr = "0"
	}
	// If string has decimal point? StringFixed gives "0"
	// Drop high-order digits if longer than intSlots
	if len(intAbsStr) > intSlots {
		intAbsStr = intAbsStr[len(intAbsStr)-intSlots:]
	}
	// Pad with leading zeros to intSlots
	if len(intAbsStr) < intSlots {
		intAbsStr = strings.Repeat("0", intSlots-len(intAbsStr)) + intAbsStr
	}
	// Now map intAbsStr onto intPic
	// Build int formatted part
	intFormatted := make([]byte, len(intPic))
	digitIdx := 0
	for i := 0; i < len(intPic); i++ {
		c := intPic[i]
		if c == 'Z' || c == '9' {
			intFormatted[i] = intAbsStr[digitIdx]
			digitIdx++
		} else if c == ',' {
			intFormatted[i] = ','
		} else {
			intFormatted[i] = byte(c)
		}
	}
	// Apply Z suppression
	// Find last index where suppression could still apply: suppression stops when we encounter non-zero digit
	// Actually spaces are only for leading zeros that are in Z positions
	suppress := true
	for i := 0; i < len(intFormatted); i++ {
		c := intPic[i]
		if c == ',' {
			if suppress {
				intFormatted[i] = ' '
			}
			continue
		}
		if c == 'Z' {
			if suppress {
				if intFormatted[i] == '0' {
					intFormatted[i] = ' '
				} else {
					suppress = false
				}
			}
		} else if c == '9' {
			// 9 always shows digit; suppression ends
			suppress = false
		}
	}
	intPartStr := string(intFormatted)

	if fracLen > 0 {
		result := intPartStr + "." + fracStr
		if len(result) < width {
			// shouldn't happen
			result = strings.Repeat(" ", width-len(result)) + result
		}
		if len(result) > width {
			result = result[len(result)-width:]
		}
		return result
	}
	if len(intPartStr) < width {
		return strings.Repeat(" ", width-len(intPartStr)) + intPartStr
	}
	return intPartStr
}

func formatCount() string {
	s := fmt.Sprintf("%d", WsCount)
	if len(s) > 3 {
		s = s[len(s)-3:]
	}
	return fmt.Sprintf("%03s", s) // zero padded to 3? PIC 9(3) displays as 3 digits zero-padded
	// But spec says unedited numeric DISPLAY prints zero-padded to digit count
}

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func readPara() {
	if discReader == nil {
		WsEofFlag = "Y"
		return
	}
	line, err := discReader.ReadString('\n')
	if err != nil {
		// EOF
		WsEofFlag = "Y"
		return
	}
	// strip trailing newline \r\n
	line = strings.TrimRight(line, "\r\n")
	// pad with spaces to record length 15
	if len(line) < 15 {
		line = line + strings.Repeat(" ", 15-len(line))
	}
	if len(line) > 15 {
		line = line[:15]
	}
	recBytes := []byte(line)
	// DR-ITEM X(6) @0
	drItem := string(recBytes[0:6])
	// DR-PRICE 9(5)V99 @6 len7 digits only
	priceStr := string(recBytes[6 : 6+7])
	priceStr = strings.TrimSpace(priceStr)
	if priceStr == "" {
		priceStr = "0"
	}
	// parse as integer then shift -2
	coeff, _ := decimal.NewFromString(priceStr)
	// priceStr contains digits, may include leading zeros
	// Use NewFromString then Shift(-2)
	priceVal := coeff.Shift(-2)
	discRec.DrItem = drItem
	discRec.DrPrice = priceVal
	// DR-PCT 9(2) @13 len2
	pctStr := strings.TrimSpace(string(recBytes[13 : 13+2]))
	if pctStr == "" {
		pctStr = "0"
	}
	var pct int64
	fmt.Sscanf(pctStr, "%d", &pct)
	discRec.DrPct = pct
}

func processPara() {
	// COMPUTE WS-DISCOUNT ROUNDED = DR-PRICE * DR-PCT / 100
	raw := discRec.DrPrice.Mul(decimal.NewFromInt(discRec.DrPct)).Shift(-2)
	rounded := roundToScale(raw, 2)
	storeDiscount(rounded)
	// COMPUTE WS-NET = DR-PRICE - WS-DISCOUNT (truncated)
	netRaw := discRec.DrPrice.Sub(WsDiscount)
	netTrunc := truncateToScale(netRaw, 2)
	storeNet(netTrunc)
	// ADD WS-NET TO WS-TOTAL-NET
	totalRaw := WsTotalNet.Add(WsNet)
	totalTrunc := truncateToScale(totalRaw, 2)
	storeTotalNet(totalTrunc)
	WsCount++
	if WsCount > 999 {
		WsCount = WsCount % 1000
	}
	WsPriceEd = formatEdited(discRec.DrPrice, "ZZ,ZZ9.99")
	WsDiscEd = formatEdited(WsDiscount, "ZZ,ZZ9.99")
	WsNetEd = formatEdited(WsNet, "ZZ,ZZ9.99")
	// DISPLAY DR-ITEM " " WS-PRICE-ED " " DR-PCT "% " WS-DISC-ED " " WS-NET-ED
	// DR-PCT display: PIC 9(2) -> zero-padded 2 digits, but sample shows? Use %02d
	pctDisplay := fmt.Sprintf("%02d", discRec.DrPct)
	// DR-ITEM is X(6) exactly 6 chars
	fmt.Printf("%s %s %s%% %s %s\n", discRec.DrItem, WsPriceEd, pctDisplay, WsDiscEd, WsNetEd)
	readPara()
}

func summaryPara() {
	WsTotalEd = formatEdited(WsTotalNet, "ZZ,ZZZ,ZZ9.99")
	countStr := fmt.Sprintf("%03d", WsCount)
	fmt.Printf("ITEMS: %s NET TOTAL: %s\n", countStr, WsTotalEd)
}

func mainPara() {
	var err error
	discFile, err = os.Open("input.dat")
	if err != nil {
		// if file not found, treat as empty
		WsEofFlag = "Y"
	} else {
		discReader = bufio.NewReader(discFile)
		readPara()
		for !isInputDone() {
			processPara()
		}
		discFile.Close()
	}
	summaryPara()
}

func main() {
	mainPara()
}

